/** String manipulation utilities. */
/**
 * Truncates text to a specified word count using Intl.Segmenter.
 * Works with any language.
 */
export declare const truncateByWord: (text: string, wordLimit?: number) => string;
/**
 * Truncates text to a specified character count using grapheme clusters.
 * Works with emoji and multi-byte characters.
 */
export declare const truncateByChar: (text: string, charLimit?: number) => string;
/** Alias for truncateByChar. */
export declare const truncateByGrapheme: (text: string, charLimit?: number) => string;
/**
 * Truncates text to a specified number of Unicode code points.
 * Safe for PostgreSQL VARCHAR columns.
 */
export declare const truncateByCodePoint: (text: string, max?: number) => string;
/**
 * Truncates text to a specified number of UTF-8 bytes.
 * Safe for byte-constrained storage like VARBINARY columns.
 */
export declare const truncateByByte: (text: string, maxBytes?: number) => string;
/** @deprecated Use truncateByWord instead. */
export declare const truncate: (text: string, wordLimit?: number) => string;
/** Removes all HTML tags from a string. */
export declare const stripTags: (s: string) => string;
/** Escapes HTML special characters to entity equivalents. */
export declare const escapeHTML: (s: string) => string;
/** Unescapes HTML entities back to original characters. */
export declare const unescapeHTML: (s: string) => string;
/** Uppercases the first character and lowercases the rest. */
export declare const ucfirst: (s: string) => string;
/** Uppercases the first character of each word. */
export declare const ucwords: (s: string) => string;
/** Removes accents and diacritical marks from characters. */
export declare const stripAccent: (s: string) => string;
/** Converts a string into a URL-friendly slug. */
export declare const slugify: (s: string, delimiter?: string) => string;
/** Splits text into sentences using Intl.Segmenter. */
export declare const getSentences: (text: string, lang?: string) => string[];
/** Extracts words from text using Intl.Segmenter. */
export declare const getArrayOfWords: (text: string, lang?: string) => string[];
/** Counts words in text using Intl.Segmenter. */
export declare const getWordCount: (text: string) => number;
/** Finds specific words within a text using Intl.Segmenter. */
export declare const findWordsIn: (text: string, words?: string[]) => string[];
/** Finds specific words within a text using RegExp. */
export declare const findWordsInWithRegExp: (text: string, words?: string[]) => string[];
/** Creates a frequency map of word occurrences in text. */
export declare const getWordMap: (text: string) => Record<string, number>;
/** Calculates Time To Read in minutes based on word count. */
export declare const getTTR: (text: string, imgcount?: number, wordsPerMinute?: number) => number;
